// components/Preloader.tsx
import React, { useState, useEffect } from 'react';

interface PreloaderProps {
  onFinish: () => void;
}

const Preloader: React.FC<PreloaderProps> = ({ onFinish }) => {
  const [isExiting, setIsExiting] = useState(false);

  useEffect(() => {
    // Função para iniciar a saída (animação de fade-out)
    const startExit = () => {
      setIsExiting(true);
      // Tempo da animação de saída (ex: 500ms) antes de remover o componente
      setTimeout(onFinish, 500); 
    };

    // Lógica Inteligente:
    // 1. Verifica se a página já carregou completamente
    const handleLoad = () => {
      // Pequeno delay opcional para garantir que o usuário veja o logo (branding)
      // Se quiser que seja instantâneo assim que carregar, remova o setTimeout interno
      setTimeout(startExit, 1000); 
    };

    // Se a página já estiver carregada (ex: refresh), roda direto
    if (document.readyState === 'complete') {
      handleLoad();
    } else {
      // Se não, espera o evento de load (imagens, scripts, styles)
      window.addEventListener('load', handleLoad);
    }

    // Cleanup: remove o event listener se o componente desmontar
    return () => window.removeEventListener('load', handleLoad);
  }, [onFinish]);

  // Se estiver saindo, adiciona uma classe CSS ou estilo para opacidade 0
  return (
    <div 
      className={`fixed inset-0 z-50 flex items-center justify-center bg-black transition-opacity duration-500 ${isExiting ? 'opacity-0 pointer-events-none' : 'opacity-100'}`}
    >
      {/* Coloque aqui o seu Logo ou Spinner */}
      <div className="text-white text-2xl font-bold animate-pulse">
        Carregando...
      </div>
    </div>
  );
};

