const AnimatedStat: React.FC<AnimatedStatProps> = ({ stat, isVisible }) => {
  const [value, setValue] = React.useState(0);
  const targetValue = stat.value; // Get the target value from stat.value
  const targetString = stat.value.toString(); // Convert the target value to string
  const isStatic = targetString.includes('/') || targetString.includes('+') || targetString.includes('%');

  useEffect(() => {
    let animationFrame: number | null = null;
    const startValue = 0;
    const duration = 2000; // milliseconds
    const startTime = performance.now();
    const range = parseFloat(targetString);

    if (isStatic) {
        setValue(Number(stat.value));
        return;
    }

    const animate = (currentTime: number) => {
      const elapsedTime = currentTime - startTime;
      const progress = Math.min(elapsedTime / duration, 1);
      const currentValue = startValue + progress * range;
      setValue(currentValue);

      if (progress < 1) {
        animationFrame = requestAnimationFrame(animate);
      }
    };

    if (isVisible) {
      animationFrame = requestAnimationFrame(animate);
    }

    return () => {
      if (animationFrame) {
        cancelAnimationFrame(animationFrame);
      }
    };
  }, [isVisible, targetString]);

  return (
    <div className={`stats__item ${!isVisible ? 'hidden' : ''}`}>
      <div className="stats__number">
        {isStatic ? `${targetString}` : value.toLocaleString('pt-BR', { maximumFractionDigits: 0 })}
      </div>
      <div className="stats__label">{stat.label}</div>
    </div>
  );
};

export default AnimatedStat;
